-- Migration: Import RSUD diagnosis catalog (DIAGNOSA, DIAGNOSA_TYPE, DIAGNOSA_CATEGORY)
-- Total: 4 diagnosis_types, 6 diagnosis_categories, 20015 diagnoses

-- 1. Enable pg_trgm for fast ILIKE search on 20k+ diagnoses
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 2. Reference table: public.diagnosis_types (from DIAGNOSA_TYPE)
CREATE TABLE IF NOT EXISTS public.diagnosis_types (
  code TEXT PRIMARY KEY,
  description TEXT NOT NULL
);

ALTER TABLE public.diagnosis_types ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'diagnosis_types' AND policyname = 'diagnosis_types_select_all'
  ) THEN
    CREATE POLICY diagnosis_types_select_all ON public.diagnosis_types FOR SELECT USING (true);
  END IF;
END $$;

ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description;

-- 3. Reference table: public.diagnosis_categories (from DIAGNOSA_CATEGORY)
CREATE TABLE IF NOT EXISTS public.diagnosis_categories (
  diag_cat SMALLINT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL
);

ALTER TABLE public.diagnosis_categories ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'diagnosis_categories' AND policyname = 'diagnosis_categories_select_all'
  ) THEN
    CREATE POLICY diagnosis_categories_select_all ON public.diagnosis_categories FOR SELECT USING (true);
  END IF;
END $$;

ON CONFLICT (diag_cat) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug;

-- 4. Extend public.diagnoses with RSUD columns
ALTER TABLE public.diagnoses
  ADD COLUMN IF NOT EXISTS dtype TEXT,
  ADD COLUMN IF NOT EXISTS is_menular TEXT REFERENCES public.diagnosis_types(code),
  ADD COLUMN IF NOT EXISTS english_name TEXT,
  ADD COLUMN IF NOT EXISTS is_surveilans BOOLEAN DEFAULT false,
  ADD COLUMN IF NOT EXISTS dtd TEXT,
  ADD COLUMN IF NOT EXISTS kode_bpjs TEXT,
  ADD COLUMN IF NOT EXISTS diagnosa_bpjs TEXT;

CREATE INDEX IF NOT EXISTS idx_diagnoses_name_trgm ON public.diagnoses USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_diagnoses_code_trgm ON public.diagnoses USING gin (code gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_diagnoses_english_trgm ON public.diagnoses USING gin (english_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_diagnoses_category ON public.diagnoses (category);
CREATE INDEX IF NOT EXISTS idx_diagnoses_dtype ON public.diagnoses (dtype);
CREATE INDEX IF NOT EXISTS idx_diagnoses_is_menular ON public.diagnoses (is_menular);

-- 5. Extend public.patient_diagnoses to support all DIAGNOSA_CATEGORY values while keeping existing compatibility
ALTER TABLE public.patient_diagnoses
  ADD COLUMN IF NOT EXISTS diag_cat SMALLINT REFERENCES public.diagnosis_categories(diag_cat);

ALTER TABLE public.patient_diagnoses
  DROP CONSTRAINT IF EXISTS patient_diagnoses_diagnosis_type_check;

ALTER TABLE public.patient_diagnoses
  ADD CONSTRAINT patient_diagnoses_diagnosis_type_check
  CHECK (diagnosis_type IN (
    'primer', 'sekunder', 'komplikasi', 'Primer', 'Sekunder',
    'utama', 'penunjang', 'masuk', 'kerja', 'kecelakaan', 'kematian'
  ));

-- Backfill diag_cat on any existing patient_diagnoses rows
UPDATE public.patient_diagnoses
SET diag_cat = CASE lower(diagnosis_type)
  WHEN 'primer' THEN 1
  WHEN 'utama' THEN 1
  WHEN 'sekunder' THEN 2
  WHEN 'penunjang' THEN 2
  WHEN 'masuk' THEN 3
  WHEN 'kerja' THEN 4
  WHEN 'kecelakaan' THEN 5
  WHEN 'kematian' THEN 6
  ELSE 1
END
WHERE diag_cat IS NULL;

-- 6. Safely clean unreferenced old seed diagnoses that won't be overwritten
DELETE FROM public.diagnoses
WHERE diagnosis_id NOT IN (SELECT DISTINCT diagnosis_id FROM public.patient_diagnoses);

-- 7. Upsert all 20015 diagnoses from DIAGNOSA.sql
