  english_name = EXCLUDED.english_name,
  is_surveilans = EXCLUDED.is_surveilans,
  dtd = EXCLUDED.dtd,
  kode_bpjs = EXCLUDED.kode_bpjs,
  diagnosa_bpjs = EXCLUDED.diagnosa_bpjs,
  is_active = true;

